from pathlib import Path
import hashlib,json,subprocess
root=Path.cwd();out=root/'docs/developer/final-acceptance/wave-04/04'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
refs=['AGENTS.md','docs/developer/react-aria-hardening-execution.md','docs/developer/react-aria-hardening-tasks.md','docs/developer/react-aria-master-task-list.md','docs/developer/backlog-execution-2026-10-15.md','docs/developer/parallel-next100/next100-c16.md','docs/developer/parallel-next100/next100-c18.md','docs/developer/react-aria-grid-contracts.md','docs/developer/react-aria-grid-reorder.md','docs/developer/react-aria-grid-host-operations.md','docs/developer/react-aria-grid-cell-acceptance.md','docs/developer/react-aria-performance.md','docs/developer/final-acceptance/wave-03-20/report.md','docs/developer/final-acceptance/wave-03-20/results.json','docs/developer/final-acceptance/wave-03-21/report.md','docs/developer/final-acceptance/wave-03-21/results.json','docs/developer/final-acceptance/wave-03-31/report.md','docs/developer/final-acceptance/wave-03-31/local-measurement-receipt.json','docs/developer/final-acceptance/wave-03-integration/controls-report.md','docs/developer/final-acceptance/wave-03-integration/push-evidence.json','docs/developer/final-acceptance/wave-03-integration/push-source-inputs.json','docs/developer/final-acceptance/wave-03-followup/status.md','docs/developer/final-acceptance/wave-03-followup/validation-results.json','docs/developer/final-acceptance/wave-03-followup/validated-source-inputs.json','docs/developer/final-acceptance/wave-03-followup/native-final.log','docs/developer/final-acceptance/wave-03-followup/units-final.log','docs/developer/final-acceptance/editor-chrome-presentation/results.json','docs/developer/final-acceptance/rich-editor-presentation/results.json','docs/developer/final-acceptance/apple-simulator/results.json']
for prefix in ['packages/ui/src/components/AppDataGrid','packages/ui/src/components/AppDataGridRowDnd','packages/ui/src/components/AppDataGridShell','packages/ui/tests/performance','apps/docs/native-fixtures/scenarios/components/AppDataGrid','apps/docs/native-fixtures/scenarios/components/AppDataGridShell']:
 refs.extend(str(p.relative_to(root)) for p in (root/prefix).rglob('*') if p.is_file() and 'dist' not in p.parts)
refs.extend('packages/ui/tests/browser/'+s for s in ['wave03-grid-successors.spec.ts','batch01-grid-focus.spec.ts','batch01-grid-reorder.spec.ts','batch05-grid-busy.spec.ts','batch05-grid-clipboard.spec.ts','batch08-grid-retry-focus.spec.ts','inventory-pointer-reorder-invalidation.spec.ts','reorder.spec.ts','hardening-grid-presentation.spec.ts'])
refs.extend(['packages/ui/src/experimental/DataGrid/DataGrid.tsx','packages/ui/src/experimental/Menu/Menu.tsx','packages/ui/src/experimental/Popover/Popover.tsx','packages/ui/src/components/Button/Button.tsx','packages/ui/src/foundation/ThemeScope.tsx','pnpm-lock.yaml','packages/ui/package.json','packages/ui/dist/index.d.ts','packages/ui/dist/experimental/index.d.ts'])
hashes={ref:sha(root/ref) for ref in sorted(set(refs)) if (root/ref).is_file()}
missing=[ref for ref in sorted(set(refs)) if not (root/ref).is_file()]
prior=json.loads((root/'docs/developer/final-acceptance/wave-03-integration/push-source-inputs.json').read_text())
prior.update(json.loads((root/'docs/developer/final-acceptance/wave-03-followup/validated-source-inputs.json').read_text()))
comparison={}
for ref,h in hashes.items():
 if ref.startswith(('packages/ui/src/','packages/ui/tests/','apps/docs/native-fixtures/')):
  comparison[ref]={'currentSha256':h,'priorSha256':prior.get(ref),'matchesPrior':prior.get(ref)==h}
(out/'input-evidence.json').write_text(json.dumps({'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'branch':subprocess.check_output(['git','branch','--show-current'],text=True).strip(),'sha256':hashes,'missing':missing,'reconciliationAgainst':'wave-03-integration/push-source-inputs.json overlaid by wave-03-followup/validated-source-inputs.json','comparison':comparison},indent=2)+'\n')
print(json.dumps({'filesHashed':len(hashes),'missing':missing,'compared':len(comparison),'matches':sum(x['matchesPrior'] for x in comparison.values()),'changedOrUnrecorded':[p for p,v in comparison.items() if not v['matchesPrior']]}))
